 public PhoneDeckWindow(bool captureWindow){
  capture=captureWindow;Text="PhoneDeck";Name="PhoneDeckWindow";Icon=SystemIcons.Application;BackColor=background;ForeColor=Color.White;Font=new Font("Segoe UI",10);ClientSize=new Size(1000,690);MinimumSize=new Size(900,670);StartPosition=FormStartPosition.CenterScreen;AutoScaleMode=AutoScaleMode.Dpi;
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(28),ColumnCount=2,RowCount=3,BackColor=background};root.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,315));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,85));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,42));Controls.Add(root);
  var header=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Margin=new Padding(0)};header.Controls.Add(TextLabel("PhoneDeck",27,Color.White,true));header.Controls.Add(TextLabel("Seu celular. Seu computador. Um toque.",10,Color.FromArgb(151,166,188)));root.Controls.Add(header,0,0);root.SetColumnSpan(header,2);
  var sidebar=new Panel{Dock=DockStyle.Fill,BackColor=card,Padding=new Padding(18),Margin=new Padding(0,0,22,0)};root.Controls.Add(sidebar,0,1);
  var sideLayout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4,Margin=new Padding(0)};sideLayout.RowStyles.Add(new RowStyle(SizeType.Absolute,34));sideLayout.RowStyles.Add(new RowStyle(SizeType.Absolute,44));sideLayout.RowStyles.Add(new RowStyle(SizeType.Percent,100));sideLayout.RowStyles.Add(new RowStyle(SizeType.Absolute,26));sidebar.Controls.Add(sideLayout);sideLayout.Controls.Add(TextLabel("CONTATOS",10,Color.FromArgb(155,171,192),true),0,0);
  var search=new TextBox{Name="ContactSearch",Dock=DockStyle.Top,BackColor=Color.FromArgb(39,47,62),ForeColor=Color.White,BorderStyle=BorderStyle.FixedSingle,Font=new Font("Segoe UI",12),AccessibleName="Buscar contatos"};sideLayout.Controls.Add(search,0,1);
  list.Name="ContactList";list.AccessibleName="Contatos";list.Dock=DockStyle.Fill;list.DrawMode=DrawMode.OwnerDrawFixed;list.ItemHeight=56;list.BorderStyle=BorderStyle.None;list.BackColor=card;list.ForeColor=Color.White;list.IntegralHeight=false;list.DrawItem+=DrawContact;list.SelectedIndexChanged+=(s,e)=>SelectContact();sideLayout.Controls.Add(list,0,2);counter.ForeColor=Color.FromArgb(151,166,188);counter.Dock=DockStyle.Fill;sideLayout.Controls.Add(counter,0,3);
  var right=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=6,Margin=new Padding(0)};right.RowStyles.Add(new RowStyle(SizeType.Absolute,34));right.RowStyles.Add(new RowStyle(SizeType.Absolute,145));right.RowStyles.Add(new RowStyle(SizeType.Absolute,64));right.RowStyles.Add(new RowStyle(SizeType.Absolute,28));right.RowStyles.Add(new RowStyle(SizeType.Absolute,128));right.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.Controls.Add(right,1,1);right.Controls.Add(TextLabel("LIGAÇÕES DO CELULAR",10,Color.FromArgb(151,166,188),true),0,0);
  var selected=new Panel{BackColor=card,Dock=DockStyle.Fill,Padding=new Padding(22),Margin=new Padding(0,0,0,16)};selectedName.Font=new Font("Segoe UI Semibold",23);selectedName.ForeColor=Color.White;selectedName.AutoEllipsis=true;selectedName.Dock=DockStyle.Top;selectedName.Height=46;selectedNumber.Font=new Font("Segoe UI",13);selectedNumber.ForeColor=Color.FromArgb(169,184,206);selectedNumber.Dock=DockStyle.Top;selectedNumber.Height=30;var selectedTitle=TextLabel("CONTATO SELECIONADO",9,Color.FromArgb(135,153,177),true);selectedTitle.Dock=DockStyle.Top;selectedTitle.Height=23;selectedTitle.AutoSize=false;selected.Controls.Add(selectedNumber);selected.Controls.Add(selectedName);selected.Controls.Add(selectedTitle);right.Controls.Add(selected,0,1);
  var calls=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,Margin=new Padding(0)};for(int i=0;i<3;i++)calls.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,33.333f));call=MakeButton("Ligar",green);answer=MakeButton("Atender",Color.FromArgb(51,112,213));hangup=MakeButton("Desligar",muted);call.Name="CallButton";answer.Name="AnswerButton";hangup.Name="HangupButton";hangup.Margin=new Padding(0);calls.Controls.Add(call,0,0);calls.Controls.Add(answer,1,0);calls.Controls.Add(hangup,2,0);right.Controls.Add(calls,0,2);
  call.Click+=(s,e)=>{var c=list.SelectedItem as Contact;if(c!=null)RunAction("--contato "+c.Id,"Solicitação de ligação enviada para "+c.Name+". Confira o Vincular ao Celular.");};answer.Click+=(s,e)=>RunAction("--atender","Solicitação de atendimento enviada. Confira o Vincular ao Celular.");hangup.Click+=(s,e)=>RunAction("--desligar","Solicitação de encerramento enviada. Confira o Vincular ao Celular.");
  var micCard=new TableLayoutPanel{Dock=DockStyle.Fill,BackColor=card,Padding=new Padding(18),ColumnCount=2,RowCount=3,Margin=new Padding(0)};micCard.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,52));micCard.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,48));micCard.RowStyles.Add(new RowStyle(SizeType.Absolute,23));micCard.RowStyles.Add(new RowStyle(SizeType.Absolute,42));micCard.RowStyles.Add(new RowStyle(SizeType.Percent,100));micCard.Controls.Add(TextLabel("MICROFONE DO WINDOWS",9,Color.FromArgb(151,166,188),true),0,0);micState.Font=new Font("Segoe UI Semibold",15);micState.AutoSize=true;micState.Text="Verificando…";micState.Name="MicrophoneStatus";micCard.Controls.Add(micState,0,1);microphone=MakeButton("Verificando…",Color.FromArgb(55,65,83));microphone.Name="MicrophoneToggle";microphone.Enabled=false;microphone.Margin=new Padding(10,0,0,0);micCard.Controls.Add(microphone,1,1);var micNote=TextLabel("Vermelho: mudo  ·  Verde: ligado",9,Color.FromArgb(151,166,188));micCard.Controls.Add(micNote,0,2);micCard.SetColumnSpan(micNote,2);right.Controls.Add(micCard,0,4);microphone.Click+=(s,e)=>{try{previousMic=AudioActions.Microphone(null,true);RenderMic(previousMic);status.Text="Estado do microfone atualizado no Windows.";}catch(Exception ex){status.Text=ex.Message;}};
  var tools=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(0,20,0,0),Margin=new Padding(0)};var audio=MakeButton("Configurar áudio de chamadas",Color.FromArgb(42,52,69));audio.Dock=DockStyle.None;audio.Width=300;audio.Height=40;audio.Click+=(s,e)=>RunAction("--audio-configure","Dispositivos de áudio das chamadas configurados.");tools.Controls.Add(audio);tools.Controls.Add(TextLabel("Chamadas via Vincular ao Celular / Bluetooth.\nO controle do Discord é separado.",9,Color.FromArgb(151,166,188)));right.Controls.Add(tools,0,5);
  status.Name="ActionStatus";status.Dock=DockStyle.Fill;status.ForeColor=Color.FromArgb(155,175,198);status.Padding=new Padding(0,17,0,0);status.Text="Pronto. Selecione um contato para ligar.";status.AutoEllipsis=true;root.Controls.Add(status,0,2);root.SetColumnSpan(status,2);
  LoadContacts();Filter("");search.TextChanged+=(s,e)=>Filter(search.Text);timer.Interval=900;timer.Tick+=(s,e)=>RefreshMic();timer.Start();Shown+=(s,e)=>{RefreshMic();if(capture)BeginInvoke(new Action(()=>{using(var bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"phonedeck-window.local.png"));}}));};FormClosed+=(s,e)=>timer.Dispose();
 }
 void LoadContacts(){
  var root=AppDomain.CurrentDomain.BaseDirectory;var folder=Path.Combine(root,"telefones");var metadata=Path.Combine(root,"telefones-contatos.json");
  try{if(File.Exists(metadata)){var data=new JavaScriptSerializer().DeserializeObject(File.ReadAllText(metadata)) as object[];if(data!=null)foreach(var entry in data){var d=entry as Dictionary<string,object>;if(d==null||!d.ContainsKey("Id")||!d.ContainsKey("Name"))continue;AddContact(folder,Convert.ToString(d["Id"]),Convert.ToString(d["Name"]));}}
   if(contacts.Count==0&&Directory.Exists(folder))foreach(var f in Directory.GetFiles(folder,"*.txt")){string id=Path.GetFileNameWithoutExtension(f);AddContact(folder,id,System.Globalization.CultureInfo.CurrentCulture.TextInfo.ToTitleCase(id));}
  }catch(Exception e){status.Text="Não consegui carregar os contatos: "+e.Message;}
 }
 void AddContact(string folder,string id,string name){if(!System.Text.RegularExpressions.Regex.IsMatch(id??"",@"^[a-z]{2,24}$"))return;var file=Path.Combine(folder,id+".txt");if(!File.Exists(file))return;var number=File.ReadAllText(file).Trim();contacts.Add(new Contact{Id=id,Name=name,Number=number});}
 void Filter(string query){var selected=list.SelectedItem as Contact;list.BeginUpdate();list.Items.Clear();foreach(var c in contacts)if(c.Name.IndexOf(query,StringComparison.CurrentCultureIgnoreCase)>=0)list.Items.Add(c);if(selected!=null&&list.Items.Contains(selected))list.SelectedItem=selected;else if(list.Items.Count>0)list.SelectedIndex=0;list.EndUpdate();counter.Text=list.Items.Count+" contatos";SelectContact();}
 void SelectContact(){var c=list.SelectedItem as Contact;selectedName.Text=c==null?"Nenhum contato":c.Name;selectedNumber.Text=c==null?"Adicione contatos na pasta telefones.":c.Number;call.Enabled=c!=null&&!busy;}
 void DrawContact(object sender,DrawItemEventArgs e){if(e.Index<0)return;var c=(Contact)list.Items[e.Index];bool selected=(e.State&DrawItemState.Selected)!=0;using(var b=new SolidBrush(selected?Color.FromArgb(43,63,72):card))e.Graphics.FillRectangle(b,e.Bounds);var circle=new Rectangle(e.Bounds.Left+8,e.Bounds.Top+13,38,38);using(var b=new SolidBrush(selected?green:Color.FromArgb(57,68,88)))e.Graphics.FillEllipse(b,circle);using(var f=new Font("Segoe UI",13,FontStyle.Bold))TextRenderer.DrawText(e.Graphics,c.Name.Substring(0,1).ToUpper(),f,circle,Color.White,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);using(var f=new Font("Segoe UI Semibold",11))TextRenderer.DrawText(e.Graphics,c.Name,f,new Rectangle(e.Bounds.Left+58,e.Bounds.Top+11,e.Bounds.Width-65,25),Color.White,TextFormatFlags.EndEllipsis);using(var f=new Font("Segoe UI",9))TextRenderer.DrawText(e.Graphics,c.Number,f,new Rectangle(e.Bounds.Left+58,e.Bounds.Top+36,e.Bounds.Width-65,22),Color.FromArgb(151,170,191),TextFormatFlags.EndEllipsis);}
 async void RunAction(string arguments,string success){if(busy)return;busy=true;call.Enabled=answer.Enabled=hangup.Enabled=false;status.Text="Enviando comando…";try{var p=Process.Start(new ProcessStartInfo(Application.ExecutablePath,arguments){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=AppDomain.CurrentDomain.BaseDirectory});int exit=await Task.Run(()=>{using(p){p.WaitForExit();return p.ExitCode;}});if(!IsDisposed)status.Text=exit==0?success:"Comando não concluído. Veja o aviso do PhoneDeck.";}catch(Exception e){if(!IsDisposed)status.Text=e.Message;}finally{busy=false;if(!IsDisposed){answer.Enabled=hangup.Enabled=true;SelectContact();}}}
 async void RefreshMic(){if(micReading)return;micReading=true;try{var state=await Task.Run(()=>AudioActions.Microphone(null,false));if(!IsDisposed){previousMic=state;RenderMic(state);if(capture&&!captured){captured=true;using(var bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"phonedeck-window.local.png"));}}}}catch{if(!IsDisposed){micState.Text="Indisponível";micState.ForeColor=Color.Gray;microphone.Enabled=false;}}finally{micReading=false;}}
 void RenderMic(string state){bool isMuted=state.Contains("silenciado"),isOn=state.Contains("ligado");micState.Text=isMuted&&isOn?"Estado misto":isMuted?"Silenciado":"Ligado";micState.ForeColor=isMuted?muted:green;microphone.BackColor=isMuted?muted:green;microphone.Text=isMuted?"Ativar microfone":"Silenciar";microphone.Enabled=true;}
